python -c "
import invoice, logline, sla, billing, uptime, progress
from duration import format_duration

cases = [0, 5, 59, 60, 61, 65, 599, 3599, 3600, 3601, 3661, 7325, 86399, 360000, 90061]

def old(seconds):
    hours, rest = divmod(int(seconds), 3600)
    minutes, secs = divmod(rest, 60)
    if hours:
        return f'{hours}h {minutes:02d}m {secs:02d}s'
    return f'{minutes}m {secs:02d}s'

ok = True
for c in cases:
    exp = old(c)
    if format_duration(c) != exp:
        ok = False; print('MISMATCH dur', c, exp, format_duration(c))
    for fn in (invoice.invoice_age, logline.line_uptime, sla.sla_elapsed, billing.billing_window, uptime.host_uptime, progress.progress_age):
        if fn(c) != exp:
            ok = False; print('MISMATCH', fn.__name__, c)

# float input parity (old code did int() cast)
for c in [3661.9, 59.9, 0.4]:
    assert format_duration(c) == old(c), c

for x in cases[:6]:
    print(x, '->', format_duration(x))
print('ALL OK' if ok else 'FAILED')
"
